<style>
:root{--o:#FF5A00;--n:#0B1220;--bg:#FFFBF8;--bd:#E8DCD3;--mut:#6B7280;--ok:#166534;--okb:#DCFCE7;--am:#92400E;--amb:#FEF3C7;--rd:#991B1B;--rdb:#FEE2E2;--or:#C2410C;--orb:#FFEDD5}
*{box-sizing:border-box}html{-webkit-text-size-adjust:100%}body{margin:0;font-family:Inter,'Bornomala',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;background:var(--bg);color:var(--n);font-size:13px;line-height:1.45}
a{color:inherit}.shell{display:flex;min-height:100vh}.side{width:232px;background:#fff;border-right:1px solid var(--bd);padding:14px 10px;display:flex;flex-direction:column;gap:6px;position:sticky;top:0;height:100vh;flex:none}
.brand{display:flex;align-items:center;gap:8px;text-decoration:none;padding:4px 6px 12px;border-bottom:1px solid var(--bd);margin-bottom:6px}.brand img{height:30px;width:auto}.brand b{font-size:12.5px;line-height:1.2}
.nav{display:flex;flex-direction:column;gap:2px;flex:1;overflow:auto}.nv{display:flex;align-items:center;gap:10px;padding:9px 10px;border-radius:9px;text-decoration:none;color:#374151;font-weight:500}.nv:hover{background:#FFF1E8}.nv.on{background:var(--n);color:#fff}.nv.on svg{color:var(--o)}.nv span{flex:1}
.bc{font-style:normal;background:var(--o);color:#fff;font-size:10.5px;font-weight:700;border-radius:20px;padding:0 6px;min-width:18px;text-align:center;line-height:18px;display:inline-block}
.who{border-top:1px solid var(--bd);padding-top:10px;font-size:12px}.who small{display:block;color:var(--mut);margin-bottom:8px}
.main{flex:1;min-width:0;display:flex;flex-direction:column}.top{display:flex;align-items:center;gap:12px;padding:10px 20px;border-bottom:1px solid var(--bd);background:#fff;position:sticky;top:0;z-index:5}
.hi small{display:block;color:var(--mut);font-size:11px}.hi b{font-size:15px}.srch{flex:1;max-width:420px;margin-left:auto}.srch input{width:100%;height:36px;border:1px solid var(--bd);border-radius:18px;padding:0 14px;font:inherit;background:#FFFBF8}
.bell{position:relative;width:36px;height:36px;border:1px solid var(--bd);border-radius:50%;display:flex;align-items:center;justify-content:center;color:var(--n);text-decoration:none;flex:none}.bell .bc{position:absolute;top:-5px;right:-5px}
.page{padding:20px;max-width:1180px;width:100%}
h1{font-size:21px;margin:0 0 4px;font-weight:700}h2{font-size:15px;margin:0 0 10px;font-weight:600}.sub{color:var(--mut);margin:0 0 14px;font-size:12px}
.card{background:#fff;border:1px solid var(--bd);border-radius:12px;padding:14px;margin-bottom:14px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:14px}.kpi{background:#fff;border:1px solid var(--bd);border-radius:12px;padding:11px 13px;text-decoration:none;display:block}.kpi span{display:block;font-size:11.5px;color:var(--mut)}.kpi b{font-size:20px;display:block;margin-top:2px}.kpi.hot b{color:var(--or)}
.btn,button{background:var(--o);color:#fff;border:0;border-radius:9px;padding:8px 14px;font:inherit;font-size:12px;font-weight:600;cursor:pointer;text-decoration:none;display:inline-block;min-height:34px}
.btn.g,button.g{background:#fff;color:var(--n);border:1px solid var(--bd)}.btn.sm,button.sm{padding:4px 10px;min-height:28px}.btn.rd,button.rd{background:#fff;color:var(--rd);border:1px solid #FCA5A5}
label{display:block;font-size:11.5px;color:var(--mut);margin:10px 0 4px}input,select,textarea{width:100%;border:1px solid var(--bd);border-radius:9px;padding:8px 10px;font:inherit;font-size:13px;background:#fff;min-height:36px}textarea{min-height:70px}
.fg{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:0 12px}
.tw{overflow:auto;border:1px solid var(--bd);border-radius:12px;background:#fff;max-height:70vh}table{width:100%;border-collapse:collapse;font-size:12px}
th{position:sticky;top:0;background:#FFF6F0;text-align:left;font-size:12px;font-weight:600;padding:8px 10px;border-bottom:1px solid var(--bd);white-space:nowrap;z-index:1}td{padding:7px 10px;border-bottom:1px solid #F3E9E2;vertical-align:middle}tr:last-child td{border-bottom:0}.n{text-align:right;font-variant-numeric:tabular-nums}
tbody tr:hover{background:#FFFAF6}tfoot td{font-weight:700;background:#FFF6F0}
.pb{display:inline-block;font-size:10.5px;font-weight:700;border-radius:9px;padding:2px 9px;text-transform:uppercase;letter-spacing:.03em;white-space:nowrap}
.pb-paid,.pb-accepted,.pb-awarded,.pb-quoted,.pb-revised,.pb-active{background:var(--okb);color:var(--ok)}.pb-due,.pb-sent,.pb-action{background:var(--orb);color:var(--or)}.pb-overdue,.pb-rejected,.pb-urgent,.pb-cancelled{background:var(--rdb);color:var(--rd)}.pb-partial,.pb-pending,.pb-info{background:var(--amb);color:var(--am)}.pb-draft,.pb-closed,.pb-declined{background:#F3F4F6;color:#4B5563}
.al{padding:10px 12px;border-radius:10px;margin-bottom:12px;font-size:12.5px}.al.ok{background:var(--okb);color:var(--ok)}.al.bad{background:var(--rdb);color:var(--rd)}
.filters{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;align-items:center}.chip{padding:5px 12px;border-radius:18px;border:1px solid var(--bd);background:#fff;text-decoration:none;font-size:12px}.chip.on{background:var(--n);color:#fff;border-color:var(--n)}
.empty{text-align:center;padding:36px 16px;color:var(--mut)}.empty b{display:block;color:var(--n);font-size:14px;margin-bottom:4px}
.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.two{display:grid;grid-template-columns:1.4fr 1fr;gap:14px}.dl{display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-top:1px solid #F3E9E2}.dl:first-child{border-top:0}.dl span{color:var(--mut)}
.ar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 13px;border:1px solid var(--bd);border-radius:10px;margin-bottom:8px;text-decoration:none;background:#fff}.ar b{font-size:15px;color:var(--or)}
.nt{display:block;padding:11px 13px;border:1px solid var(--bd);border-radius:10px;margin-bottom:8px;background:#fff;text-decoration:none}.nt.un{border-left:4px solid var(--o);background:#FFFAF6}.nt b{display:block}.nt small{color:var(--mut)}
.bnav{display:none}.sheet{display:none}
@media(max-width:860px){.side{display:none}.top{padding:8px 12px}.hi b{font-size:14px}.srch{display:none}.page{padding:14px 14px 90px}.two{grid-template-columns:1fr}
.bnav{display:flex;position:fixed;left:0;right:0;bottom:0;background:#fff;border-top:1px solid var(--bd);z-index:20;padding:4px 0 max(4px,env(safe-area-inset-bottom))}.bnav a{flex:1;text-align:center;text-decoration:none;font-size:10.5px;color:var(--mut);padding:6px 0;display:flex;flex-direction:column;align-items:center;gap:2px}.bnav a.on{color:var(--o);font-weight:700}
.sheet.open{display:flex;position:fixed;inset:0;background:rgba(11,18,32,.45);z-index:30;align-items:flex-end}.sh{background:#fff;width:100%;border-radius:16px 16px 0 0;padding:14px 16px calc(14px + env(safe-area-inset-bottom));display:grid;grid-template-columns:1fr 1fr;gap:8px}.sh b{grid-column:1/-1}.sh a{display:flex;gap:8px;align-items:center;padding:11px;border:1px solid var(--bd);border-radius:10px;text-decoration:none}.sh form{grid-column:1/-1}.sh button{width:100%}
.mcards table,.mcards thead{display:block}.mcards thead{display:none}.mcards tr{display:block;border:1px solid var(--bd);border-radius:10px;margin:8px;padding:6px 10px;background:#fff}.mcards td{display:flex;justify-content:space-between;gap:10px;border:0;padding:4px 0;text-align:right}.mcards td:before{content:attr(data-l);color:var(--mut);text-align:left}.mcards .tw{border:0;background:none;max-height:none}}
@media print{.side,.top,.bnav,.sheet,.noprint{display:none!important}.page{padding:0}body{background:#fff}}
</style>
